	if diff.Results[0].Before.Rule.Status != StatusPass || diff.Results[0].After.Rule.Status != StatusPass {
		t.Errorf("statuses = %q / %q", diff.Results[0].Before.Rule.Status, diff.Results[0].After.Rule.Status)
